sys_script_include.script:
var CPMUtil = Class.create();
CPMUtil.prototype = {
  initialize: function() {
    this.K = new CPMConst();
  },

  // application setting (system property)
  prop: function(name, fallback) {
    return gs.getProperty(this.K.PREFIX + '.' + name, fallback);
  },

  intProp: function(name, fallback) {
    var value = parseInt(this.prop(name, ''), 10);
    return isNaN(value) ? fallback : value;
  },

  // true for a checked boolean field value
  on: function(value) {
    return value === true || value === 1 || value === '1' || value === 'true';
  },

  // today as YYYY-MM-DD
  today: function() {
    return new GlideDateTime().getLocalDate().getValue();
  },

  // adds days to a YYYY-MM-DD date (UTC, no time zone drift)
  addDays: function(date, days) {
    var gdt = new GlideDateTime(date + ' 00:00:00');
    gdt.addDaysUTC(days);
    return gdt.getValue().substring(0, 10);
  },

  daysBetween: function(from, to) {
    var start = new GlideDateTime(from + ' 00:00:00').getNumericValue();
    var end = new GlideDateTime(to + ' 00:00:00').getNumericValue();
    return Math.round((end - start) / 86400000);
  },

  // last day counted as "expiring soon"
  horizon: function() {
    return this.addDays(this.today(), this.intProp('warning_days', 30));
  },

  // the state people see today, whatever the nightly job has done
  effective: function(state, validUntil) {
    if (state != this.K.STATE.APPROVED || !validUntil) return state;
    if (validUntil < this.today()) return this.K.STATE.EXPIRED;
    return validUntil <= this.horizon() ? this.K.VIEW.EXPIRING : this.K.STATE.APPROVED;
  },

  // traffic light from the share of approved controls
  riskFor: function(total, coverage) {
    var risk = this.K.RISK;
    if (!total) return risk.NOT_ASSESSED;
    if (coverage >= this.intProp('green_min', 80)) return risk.GREEN;
    return coverage >= this.intProp('yellow_min', 50) ? risk.YELLOW : risk.RED;
  },

  // owner of a CI: owned by, else managed by, else the fallback user
  ownerOf: function(ci) {
    return ci.getValue('owned_by') || ci.getValue('managed_by') || this.prop('fallback_owner', '');
  },

  // setup problems, shown to the compliance team: a missing field, or a Script Include that is not up to date
  healthProblems: function() {
    var T = this.K.TABLE;
    var problems = [];
    var fields = {};
    fields[T.CONTROL] = ['reference', 'name', 'description', 'guidance', 'framework', 'targets', 'include_components', 'active', 'validity_days'];
    fields[T.MAPPING] = ['number', 'control', 'target', 'owner', 'via_service', 'state', 'valid_until', 'active'];
    fields[T.EVIDENCE] = ['number', 'mapping', 'status', 'submitted_by', 'submitted_on', 'review_by', 'reviewed_on', 'valid_until', 'scope_snapshot', 'seal', 'review_comment'];
    Object.keys(fields).forEach(function(table) {
      var gr = new GlideRecord(table);
      fields[table].forEach(function(field) {
        if (!gr.isValidField(field)) problems.push('The table ' + table + ' has no field named "' + field + '".');
      });
    });

    // newest functions each Script Include must have
    var needs = [
      ['CPMStats', function() { return new CPMStats(); }, ['approvals', 'followCounts', 'serviceCoverage', 'frameworks']],
      ['CPMNotify', function() { return new CPMNotify(); }, ['teamDigest', 'assigned', 'ownerDigest']],
      ['CPMMapping', function() { return new CPMMapping(); }, ['syncAllControls', 'describeTargets', 'refreshOwners']],
      ['CPMReview', function() { return new CPMReview(); }, ['stampReviewer', 'verify']],
      ['CPMLookup', function() { return new CPMLookup(); }, ['namesFromMappings', 'ownersOf']],
      ['CPMAccess', function() { return new CPMAccess(); }, ['isAdmin', 'canViewTarget']],
      ['CPMEvidence', function() { return new CPMEvidence(); }, ['addFile', 'submit', 'getFile']]
    ];
    needs.forEach(function(need) {
      try {
        var instance = need[1]();
        need[2].forEach(function(method) {
          if (typeof instance[method] !== 'function') problems.push(need[0] + ' is out of date (no ' + method + '): replace the whole Script Include.');
        });
      } catch (e) {
        problems.push(need[0] + ' is missing or broken: ' + e.message);
      }
    });
    return problems;
  },

  type: 'CPMUtil'
};
